def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    def is_vline(r,c):
        if g[r][c]==0: return False
        left = c>0 and g[r][c-1]==g[r][c]
        right = c<w-1 and g[r][c+1]==g[r][c]
        return not left and not right and ((r>0 and g[r-1][c]==g[r][c]) or (r<h-1 and g[r+1][c]==g[r][c]))
    for r in range(h):
        row=g[r]
        cols=[c for c in range(w) if row[c]!=0]
        if not cols or len(set(row[c] for c in cols))!=1: continue
        col=row[cols[0]]
        c=0
        while c<w:
            if row[c]==0:
                s=c
                while c<w and row[c]==0: c+=1
                if s>0 and c<w and row[s-1]==col and row[c]==col and any(is_vline(rr,s) for rr in range(h)):
                    for k in range(s,c): out[r][k]=col
            else: c+=1
    return out
