def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    bars=[r for r in range(h) if any(g[r][c]!=0 and ((c>0 and g[r][c-1]==g[r][c]) or (c<w-1 and g[r][c+1]==g[r][c])) for c in range(w))]
    def bar_color(b,s):
        if g[b][s]!=0: return g[b][s]
        for c in range(s-1,-1,-1):
            if g[b][c]!=0: return g[b][c]
        for c in range(s+1,w):
            if g[b][c]!=0: return g[b][c]
    for s in range(w):
        r=0
        while r<h:
            if g[r][s]!=0 and (r==0 or g[r-1][s]!=g[r][s]):
                e=r
                while e+1<h and g[e+1][s]==g[r][s]: e+=1
                col=g[r][s]
                in_bar=any((s>0 and g[rr][s-1]==col) or (s<w-1 and g[rr][s+1]==col) for rr in range(r,e+1))
                if not in_bar:
                    above=[b for b in bars if b<r]; below=[b for b in bars if b>e]
                    da=r-above[-1] if above else 99
                    db=below[0]-e if below else 99
                    if da<=db and above:
                        b=above[-1]; bc=bar_color(b,s)
                        for rr in range(0,b+1): out[rr][s]=bc
                        for rr in range(b+1,e+1): out[rr][s]=col
                    elif below:
                        b=below[0]; bc=bar_color(b,s)
                        for rr in range(b,h): out[rr][s]=col
                        for rr in range(r,b): out[rr][s]=bc
                r=e+1
            else: r+=1
    return out
